```c
#include <stdio.h>
#include <string.h>

#define N 5

struct Empleado {
    int id;
    char nombre[50];
    float salario;
};

int main() {
    struct Empleado empleados[N];
    float suma = 0;

    for (int i = 0; i < N; i++) {
        printf("Empleado %d\n", i + 1);
        printf("  ID: ");
        scanf("%d", &empleados[i].id);
        printf("  Nombre: ");
        scanf("%s", empleados[i].nombre);
        printf("  Salario: ");
        scanf("%f", &empleados[i].salario);
        suma += empleados[i].salario;
    }

    float promedio = suma / N;
    printf("\nPromedio de salarios: %.2f\n", promedio);

    return 0;
}
```

Nota que para `scanf` con el nombre no se necesita `&` porque `nombre` ya es la dirección del arreglo de chars. Para los demás campos sí se usa `&`. ¿Tiene sentido esa diferencia?
